from migrate import migrate

def test_migrates_legacy_fields_without_mutation():
    original = {'version':1, 'retry':4, 'timeout_ms':2500, 'feature_x':True}
    result = migrate(original)
    assert original == {'version':1, 'retry':4, 'timeout_ms':2500, 'feature_x':True}
    assert result == {'version':3, 'service':{'retry':{'attempts':4}, 'timeout_seconds':2.5}, 'feature_x':True}

def test_version_two_and_three_are_supported_idempotently():
    v2 = {'version':2, 'service':{'retries':2, 'timeout':1.25}, 'tag':'x'}
    expected = {'version':3, 'service':{'retry':{'attempts':2}, 'timeout_seconds':1.25}, 'tag':'x'}
    assert migrate(v2) == expected
    assert migrate(expected) == expected

