class CircuitOpen(RuntimeError):
    pass

class RetryCircuit:
    def __init__(self, attempts=3, base_delay=0.1, failure_threshold=2, reset_after=5.0, clock=None, sleep=None):
        self.attempts = attempts
        self.base_delay = base_delay
        self.failure_threshold = failure_threshold
        self.reset_after = reset_after
        self.clock = clock
        self.sleep = sleep

    def call(self, function):
        return function()

