import pytest
from retrying import CircuitOpen, RetryCircuit

class Time:
    def __init__(self): self.now = 0.0; self.delays = []
    def clock(self): return self.now
    def sleep(self, value): self.delays.append(value)

def test_retry_delays_and_attempt_limit():
    t = Time(); circuit = RetryCircuit(attempts=3, base_delay=.5, clock=t.clock, sleep=t.sleep)
    calls=[]
    def work():
        calls.append(1)
        if len(calls) < 3: raise ValueError('x')
        return 'ok'
    assert circuit.call(work) == 'ok'
    assert len(calls) == 3 and t.delays == [.5, 1.0]

def test_open_half_open_and_recovery():
    t=Time(); circuit=RetryCircuit(attempts=1, failure_threshold=2, reset_after=5, clock=t.clock, sleep=t.sleep)
    def bad(): raise ValueError('x')
    for _ in range(2):
        with pytest.raises(ValueError): circuit.call(bad)
    with pytest.raises(CircuitOpen): circuit.call(lambda:'blocked')
    t.now=5
    assert circuit.call(lambda:'ok') == 'ok'
    assert circuit.call(lambda:'still-ok') == 'still-ok'

