import pytest
from graph_scheduler import GraphError, execution_waves

def test_deterministic_parallel_waves():
    tasks={'fetch':[], 'parse':['fetch'], 'audit':['fetch'], 'save':['parse','audit'], 'notify':['save']}
    assert execution_waves(tasks) == [['fetch'], ['audit','parse'], ['save'], ['notify']]

def test_missing_dependency():
    with pytest.raises(GraphError, match='missing.*unknown'):
        execution_waves({'build':['unknown']})

def test_cycle_includes_path():
    with pytest.raises(GraphError, match=r'a.*b.*c.*a'):
        execution_waves({'a':['b'], 'b':['c'], 'c':['a']})

